// Move a calendar date by a number of days and name the weekday.
// date is "YYYY-MM-DD": exactly four year digits (0000 to 9999), a '-', two
// month digits, a '-', two day digits, nothing else. Dates are in the
// proleptic Gregorian calendar: the Gregorian leap rule applies to every
// year, year 0 included. A year is a leap year when it is divisible by 4,
// except years divisible by 100 that are not divisible by 400, so 0000,
// 2000 and 2400 are leap years and 1900 and 2100 are not.
// Return the date that is days days later (earlier when days is negative)
// as "YYYY-MM-DD Www", zero-padded the same way, where Www is the weekday:
// one of Mon Tue Wed Thu Fri Sat Sun.
// Return "invalid" if date is not of that form or names a day that does
// not exist (month 00 or 13, day 00, 2023-02-29, 2023-04-31).
// Return "out of range" if the resulting date would fall before 0000-01-01
// or after 9999-12-31.
// Examples:
//   date_shift("2024-02-28", 1) == "2024-02-29 Thu"
//   date_shift("1900-02-28", 1) == "1900-03-01 Thu"
fn date_shift(date: Str, days: Int) -> Str {
  let cs = chars(date);
  if len(cs) != 10 || cs[4] != "-" || cs[7] != "-" {
    return "invalid";
  }
  if !all([0, 1, 2, 3, 5, 6, 8, 9], |i| is_digit(cs[i])) {
    return "invalid";
  }
  let y = unwrap_or(parse_int(substr(date, 0, 4)), 0);
  let m = unwrap_or(parse_int(substr(date, 5, 7)), 0);
  let d = unwrap_or(parse_int(substr(date, 8, 10)), 0);
  if m < 1 || m > 12 || d < 1 || d > month_len(y, m) {
    return "invalid";
  }
  let start = day_number(y, m, d);
  let last = day_number(9999, 12, 31);
  if days < 0 - start || days > last - start {
    return "out of range";
  }
  let mut z = start + days;
  // walk forward from year 0 in 400-year cycles of 146097 days
  let mut yy = 400 * (z / 146097);
  z = z % 146097;
  while z >= year_len(yy) {
    z = z - year_len(yy);
    yy = yy + 1;
  }
  let mut mm = 1;
  while z >= month_len(yy, mm) {
    z = z - month_len(yy, mm);
    mm = mm + 1;
  }
  let names = ["Sat", "Sun", "Mon", "Tue", "Wed", "Thu", "Fri"];
  let wd = names[day_number(yy, mm, z + 1) % 7];
  pad(yy, 4) ++ "-" ++ pad(mm, 2) ++ "-" ++ pad(z + 1, 2) ++ " " ++ wd
}

fn pad(n: Int, width: Int) -> Str {
  let s = show(n);
  repeat("0", max(0, width - str_len(s))) ++ s
}

fn leap(y: Int) -> Bool {
  y % 4 == 0 && (y % 100 != 0 || y % 400 == 0)
}

fn year_len(y: Int) -> Int {
  if leap(y) { 366 } else { 365 }
}

fn month_len(y: Int, m: Int) -> Int {
  match m {
    2 => if leap(y) { 29 } else { 28 },
    4 | 6 | 9 | 11 => 30,
    _ => 31,
  }
}

// Days since 0000-01-01 (a Saturday).
fn day_number(y: Int, m: Int, d: Int) -> Int {
  let mut n = 365 * y + (y + 3) / 4 - (y + 99) / 100 + (y + 399) / 400;
  for k in range(1, m) {
    n = n + month_len(y, k);
  }
  n + d - 1
}
